select * from category

    tenant_id = #{tenantId} and tenant_id = #{scopeTenant}

        and name like concat('%',#{query.name},'%')


        and type = #{query.type}


order by sort asc , create_time desc


select * from category
where status = 1 and tenant_id = #{tenantId} and tenant_id = #{scopeTenant}

    and type = #{type}

order by sort asc,create_time desc
